"mutually":{a:[{tr:"z. karşılıklı olarak",ex:"The two companies reached a mutually beneficial agreement after weeks of negotiation.",exTr:"İki şirket, haftalarca süren müzakerelerin ardından karşılıklı olarak yararlı bir anlaşmaya vardı."}]},
"nonlinear":{a:[{tr:"s. doğrusal olmayan",ex:"Climate systems often behave in a nonlinear way, making long-term predictions difficult.",exTr:"İklim sistemleri genellikle doğrusal olmayan biçimde davranır, bu da uzun vadeli tahminleri zorlaştırır."}]},
"painter":{a:[{tr:"i. ressam",ex:"The exhibition featured landscapes created by a painter who traveled extensively across Europe.",exTr:"Sergide, Avrupa'yı uzun süre gezen bir ressamın yarattığı manzara tabloları yer aldı."}]},
"perceived":{a:[{tr:"s. algılanan",ex:"The perceived risk of the vaccine was much higher than the actual statistics showed.",exTr:"Aşının algılanan riski, gerçek istatistiklerin gösterdiğinden çok daha yüksekti."}]},
"postgraduate":{a:[{tr:"s. lisansüstü; i. lisansüstü öğrenci",ex:"Many postgraduate students choose to specialize in renewable energy engineering these days.",exTr:"Günümüzde birçok lisansüstü öğrenci, yenilenebilir enerji mühendisliğinde uzmanlaşmayı tercih ediyor."}]},
"ready-made":{a:[{tr:"s. hazır, hazır yapılmış",ex:"Busy parents often rely on ready-made meals to save time during the week.",exTr:"Yoğun ebeveynler, hafta içinde zaman kazanmak için sık sık hazır yemeklere güvenir."}]},
