"runner":{a:[{tr:"i. koşucu",ex:"The young runner trained for months before qualifying for the national championship.",exTr:"Genç koşucu, ulusal şampiyonaya katılmaya hak kazanmadan önce aylarca antrenman yaptı.",yz:4},{tr:"i. yolluk, uzun dar halı",ex:"A red runner stretched down the center of the hallway toward the main entrance.",exTr:"Kırmızı bir yolluk, koridorun ortasından ana girişe doğru uzanıyordu.",yz:1}]},
"sixth":{a:[{tr:"s. altıncı; i. altıda bir",ex:"The company celebrated its sixth anniversary with a small gathering for employees.",exTr:"Şirket, altıncı yıl dönümünü çalışanlar için küçük bir buluşmayla kutladı."}]},
"spiritual":{a:[{tr:"s. manevi, ruhani",ex:"Many patients report finding spiritual comfort through meditation during long illnesses.",exTr:"Birçok hasta, uzun süren hastalıklar boyunca meditasyon yoluyla manevi bir rahatlama bulduğunu belirtiyor."}]},
