"swept":{a:[{tr:"s. süpürülmüş, temizlenmiş",ex:"The freshly swept courtyard looked spotless before the ceremony began.",exTr:"Yeni süpürülmüş avlu, tören başlamadan önce tertemiz görünüyordu."}]},
"synonymous":{a:[{tr:"s. eşanlamlı; özdeşleşmiş",ex:"In many people's minds, the brand has become synonymous with reliability and quality.",exTr:"Birçok insanın zihninde, marka güvenilirlik ve kaliteyle özdeşleşmiş durumda."}]},
"territorial":{a:[{tr:"s. bölgesel, toprakla ilgili",ex:"The two countries have been negotiating over a long-standing territorial dispute for decades.",exTr:"İki ülke, on yıllardır süregelen bölgesel bir anlaşmazlık üzerine görüşmeler yürütüyor."}]},
"tired":{a:[{tr:"s. yorgun",ex:"After twelve hours in the emergency room, the nurses were too tired to stand.",exTr:"Acil serviste on iki saat geçirdikten sonra hemşireler ayakta duramayacak kadar yorgundu."}]},
"uplift":{a:[{tr:"i. yükselme, moral; f. yükseltmek, moral vermek",ex:"Volunteers hoped the charity concert would uplift the spirits of flood survivors.",exTr:"Gönüllüler, hayır konserinin sel mağdurlarının moralini yükseltmesini umuyordu."}]},
"workforce":{a:[{tr:"i. işgücü",ex:"Automation is expected to transform the workforce across many manufacturing industries.",exTr:"Otomasyonun, birçok imalat sektöründe işgücünü dönüştürmesi bekleniyor."}]},
