"commercially":{a:[{tr:"z. ticari olarak",ex:"The new vaccine will not be commercially available until further trials are completed.",exTr:"Yeni aşı, ek denemeler tamamlanana kadar ticari olarak satışa sunulmayacak."}]},
"confidential":{a:[{tr:"s. gizli, mahrem",ex:"Employees are required to keep all client records strictly confidential at all times.",exTr:"Çalışanların, tüm müşteri kayıtlarını her zaman kesinlikle gizli tutması gerekir."}]},
