"swift":{a:[{tr:"s. hızlı, çevik",ex:"The committee praised the government's swift response to the earthquake disaster.",exTr:"Komite, hükümetin deprem felaketine gösterdiği hızlı tepkiyi övdü.",yz:4},{tr:"i. ebabil (bir kuş türü)",ex:"A swift darted across the evening sky, catching insects in mid-flight.",exTr:"Bir ebabil, akşam gökyüzünde uçarken böcekleri havada yakalayarak süzüldü.",yz:1}]},
"tender":{a:[{tr:"s. yumuşak; hassas, şefkatli",ex:"The meat becomes tender only after several hours of slow cooking.",exTr:"Et, ancak birkaç saat ağır ateşte piştikten sonra yumuşuyor.",yz:3},{tr:"i. ihale, teklif",ex:"Three firms submitted a tender for the construction of the new bridge.",exTr:"Üç firma, yeni köprünün inşası için ihaleye teklif verdi.",yz:3},{tr:"f. (resmî olarak) sunmak, teklif vermek",ex:"She tendered her resignation the morning after the vote.",exTr:"Oylamanın ertesi sabahı istifasını sundu.",yz:2}]},
"voter":{a:[{tr:"i. seçmen",ex:"Election officials distributed pamphlets to help every voter understand the new registration process.",exTr:"Seçim yetkilileri, her seçmenin yeni kayıt sürecini anlamasına yardımcı olmak için broşürler dağıttı."}]},
