"alternatively":{a:[{tr:"z. alternatif olarak",ex:"Students can submit the assignment online, or alternatively, hand in a printed copy.",exTr:"Öğrenciler ödevi çevrim içi teslim edebilir ya da alternatif olarak basılı bir kopya verebilir."}]},
"ashamed":{a:[{tr:"s. utanmış, mahcup",ex:"He felt deeply ashamed after realizing how carelessly he had spoken to his colleague.",exTr:"İş arkadaşına ne kadar dikkatsizce konuştuğunu fark edince derin bir utanç duydu."}]},
"braille":{a:[{tr:"i. Braille alfabesi (körler alfabesi)",ex:"The library added several books printed in braille to support visually impaired readers.",exTr:"Kütüphane, görme engelli okuyucuları desteklemek için braille alfabesiyle basılmış birkaç kitap ekledi."}]},
