"keeper":{a:[{tr:"i. bakıcı, koruyucu, gözetici",ex:"The zoo hired an experienced keeper to look after the newly arrived elephants.",exTr:"Hayvanat bahçesi, yeni gelen filleri bakmak için deneyimli bir bakıcı işe aldı."}]},
"ladder":{a:[{tr:"i. merdiven",ex:"Workers used a tall ladder to reach the damaged section of the building's roof.",exTr:"İşçiler, binanın çatısının hasarlı bölümüne ulaşmak için uzun bir merdiven kullandı.",yz:4},{tr:"f. (çorapta) kaçmak",ex:"Her tights began to ladder the moment they snagged on the edge of the chair.",exTr:"Sandalyenin kenarına takıldığı anda taytı kaçmaya başladı.",yz:1}]},
"lobby":{a:[{tr:"f. lobi yapmak, baskı grubu oluşturmak",ex:"Environmental groups continue to lobby lawmakers for stricter regulations on industrial carbon emissions.",exTr:"Çevre grupları, endüstriyel karbon emisyonlarına yönelik daha sıkı düzenlemeler için yasa koyucular üzerinde lobi yapmaya devam ediyor.",yz:4},{tr:"i. lobi, giriş salonu",ex:"Guests waited in the hotel lobby while their rooms were being prepared for check-in.",exTr:"Misafirler, odaları check-in için hazırlanırken otel lobisinde bekledi.",yz:3}]},
"mathematically":{a:[{tr:"z. matematiksel olarak",ex:"The engineer proved mathematically that the bridge design could support the expected load.",exTr:"Mühendis, köprü tasarımının beklenen yükü taşıyabileceğini matematiksel olarak kanıtladı."}]},
"modest":{a:[{tr:"s. mütevazı, alçakgönüllü",ex:"Despite winning numerous awards, the scientist remained modest about her groundbreaking contributions to medicine.",exTr:"Sayısız ödül kazanmasına rağmen bilim insanı, tıbba yaptığı çığır açan katkılar konusunda mütevazı kaldı."}]},
"newest":{a:[{tr:"s. en yeni",ex:"Consumers lined up outside the store to purchase the newest smartphone model released this week.",exTr:"Tüketiciler, bu hafta piyasaya sürülen en yeni akıllı telefon modelini satın almak için mağazanın önünde sıraya girdi."}]},
