"fossilised":{a:[{tr:"s. fosilleşmiş; (mecazi) kemikleşmiş, değişmeye kapalı",ex:"Critics argued that the committee's fossilised attitudes prevented any meaningful reform of the outdated curriculum.",exTr:"Eleştirmenler, komitenin kemikleşmiş tutumlarının modası geçmiş müfredatta anlamlı bir reformu engellediğini savundu."}]},
"gasoline":{a:[{tr:"i. benzin",ex:"Rising gasoline prices have pushed many commuters to consider public transportation instead of driving to work.",exTr:"Artan benzin fiyatları, birçok işe gidip gelen kişiyi araba yerine toplu taşımayı düşünmeye itti."}]},
"genesis":{a:[{tr:"i. doğuş, köken, başlangıç",ex:"Historians trace the genesis of the movement to a series of local protests in the 1960s.",exTr:"Tarihçiler, hareketin doğuşunu 1960'lardaki bir dizi yerel proteste dayandırıyor."}]},
"geometry":{a:[{tr:"i. geometri",ex:"Students apply basic geometry principles when calculating the area and volume of everyday objects.",exTr:"Öğrenciler, günlük nesnelerin alanını ve hacmini hesaplarken temel geometri ilkelerini uygular."}]},
"grill":{a:[{tr:"i. ızgara",ex:"Neighbors gathered around the grill as the smell of roasting vegetables filled the summer evening air.",exTr:"Kavrulan sebzelerin kokusu yaz akşamının havasını doldururken komşular ızgaranın etrafında toplandı."},{tr:"f. sıkı sorguya çekmek",ex:"Reporters began to grill the minister about the missing funds during the press conference.",exTr:"Muhabirler, basın toplantısı sırasında bakanı kayıp fonlar hakkında sıkı sorguya çekmeye başladı."}]},
"hand-held":{a:[{tr:"s. elde taşınan, el tipi",ex:"Paramedics now carry a hand-held device that can measure blood oxygen levels within seconds.",exTr:"Sağlık görevlileri artık kan oksijen düzeyini saniyeler içinde ölçebilen el tipi bir cihaz taşıyor."}]},
"hard-won":{a:[{tr:"s. zor kazanılmış, emekle elde edilmiş",ex:"The team celebrated its hard-won victory after months of intense training and several narrow defeats.",exTr:"Takım, aylarca süren yoğun antrenman ve birkaç dar mağlubiyetin ardından zor kazanılmış zaferini kutladı."}]},
