"fresh-cut":{a:[{tr:"s. yeni kesilmiş, taze",ex:"The florist arranged fresh-cut roses into an elegant bouquet for the wedding reception.",exTr:"Çiçekçi, düğün resepsiyonu için taze kesilmiş güllerden zarif bir buket hazırladı."}]},
