"full-length":{a:[{tr:"s. tam boy, tam uzunlukta",ex:"The director released a full-length version of the documentary after years of editing.",exTr:"Yönetmen, yıllar süren kurgu çalışmasının ardından belgeselin tam uzunlukta bir sürümünü yayımladı."}]},
"ground-floor":{a:[{tr:"s. zemin kat(a ait), zemin kattaki",ex:"The elderly couple requested a ground-floor apartment because climbing stairs had become increasingly difficult.",exTr:"Yaşlı çift, merdiven çıkmak giderek zorlaştığı için zemin kattaki bir daire talep etti."}]},
"hand-to-mouth":{a:[{tr:"s. kıt kanaat, ancak geçinmeye yeten",ex:"Before the factory opened, most families in the village survived on a hand-to-mouth existence.",exTr:"Fabrika açılmadan önce köydeki çoğu aile kıt kanaat bir yaşam sürdürerek hayatta kalıyordu."}]},
